export const POWERFACTORY_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/powerfactory-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getPowerFactoryStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(POWERFACTORY_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
